import{_ as n,I as l,c as i,o as s,j as t,ap as o,a as e,J as d}from"./chunks/framework.BVMg0REN.js";const k=JSON.parse('{"title":"首次启动","description":"","frontmatter":{},"headers":[],"relativePath":"Started/FirstLaunch.md","filePath":"zh/Started/FirstLaunch.md","lastUpdated":1786376073000}'),c={name:"Started/FirstLaunch.md"},h={id:"首次启动",tabindex:"-1"};function g(u,a,m,p,b,f){const r=l("Badge");return s(),i("div",null,[t("h1",h,[a[0]||(a[0]=e("首次启动")),d(r,{type:"tip",text:"新手"}),a[1]||(a[1]=e()),a[2]||(a[2]=t("a",{class:"header-anchor",href:"#首次启动","aria-label":"Permalink to “首次启动”"},"​",-1))]),a[3]||(a[3]=o('<div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>首次启动 <code>MaaYuan</code> 会自动安装/更新依赖库，请耐心等待安装任务完成，如任务长时间未完成，请查阅<a href="./../FAQ/01-general-issues.html">【常见问题-问题排查】</a>，后续每天第一次启动 <code>MaaYuan</code> 都会先自启动检测当前版本及依赖库，是正常操作。</p></div><h2 id="第一次运行" tabindex="-1">第一次运行 <a class="header-anchor" href="#第一次运行" aria-label="Permalink to “第一次运行”">​</a></h2><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to “Windows”">​</a></h3><ul><li>双击运行 <code>MaaYuan.exe</code> 。</li><li>初次运行若<strong>报错</strong>，找到文件夹内 <strong>DependencySetup_依赖库安装_win.bat</strong> → 右键「以管理员身份运行」→ 根据提示操作 → 重启电脑；若不成功请查阅<a href="./../Started/Install.html#安装运行环境-依赖库">【下载与安装-安装运行环境（依赖库）】</a>。</li></ul><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to “macOS”">​</a></h3><ul><li><strong>开启运行权限</strong>：终端输入指令：<code>sudo spctl --master-disable</code>，输入密码（输入时无显示，确认后回车）。</li><li>打开 <strong>系统设置 → 隐私与安全性 → 安全性</strong> → 选择「任何来源」。</li><li>打开 <strong>系统设置 → 隐私与安全性</strong> → 底部「已阻止使用的应用」→ 点击「仍然允许」。</li><li><strong>处理弹窗</strong>：后续若多次弹窗阻止，保持「隐私与安全性」窗口打开，重复点击「仍然允许」。</li><li><strong>验证</strong>：点击文件夹中 <code>MaaYuan</code> 成功后会弹出 <code>MaaYuan</code> 主窗口；若无反应，重新执行权限指令。</li><li><strong>启动</strong>：进入安装目录，找到 <code>MaaYuan</code> <strong>文件</strong> → 右键「制作替身」（快捷方式），将替身拖到桌面/启动栏，后续直接点击启动。</li></ul><h2 id="模拟器适配" tabindex="-1">模拟器适配 <a class="header-anchor" href="#模拟器适配" aria-label="Permalink to “模拟器适配”">​</a></h2><ul><li><strong>模拟器支持</strong>：可参考 MAA 文档站，查阅<a href="https://docs.maa.plus/zh-cn/manual/device/" target="_blank" rel="noreferrer">模拟器和设备支持</a>，确认正在使用的模拟器支持情况。</li><li><strong>分辨率</strong>：模拟器分辨率应为手机版 720×1280 DPI 320。</li></ul><h2 id="代号鸢-如鸢客户端下载" tabindex="-1">代号鸢/如鸢客户端下载 <a class="header-anchor" href="#代号鸢-如鸢客户端下载" aria-label="Permalink to “代号鸢/如鸢客户端下载”">​</a></h2><ul><li>推荐使用官网下载，代号鸢可使用<strong>biubiu加速器</strong>下载。下载后需要将apk文件导入模拟器安装。</li></ul><table><tbody><tr><td align="center">游戏名</td><td align="center" colspan="3">代号鸢</td><td align="center">如鸢</td></tr><tr><td align="center">区服</td><td align="center">台服</td><td align="center" colspan="2">港澳服</td><td align="center">国服</td></tr><tr><td align="center">游戏语言</td><td align="center" colspan="2">繁中</td><td align="center" colspan="2">简中</td></tr><tr><td align="center">官服</td><td align="center"><a href="https://ashesofthekingdom.sialiagames.com.tw/prism-ledum2pm/?access=1002_2002_3003#/">官网</a>/谷歌 </td><td align="center">谷歌</td><td align="center"><a href="https://ashesofthekingdom.qookkagames.com/prism-leduk39b/?access=1004_2001_3003#/">官网</a></td><td align="center"><a href="https://yuan.lingxigames.com/">官网</a>/Tap </td></tr><tr><td align="center">渠道服</td><td align="center" colspan="3">/</td><td align="center">九游/小米/华为/OPPO</td></tr></tbody></table><ul><li>关于下载渠道<strong>Tap版本</strong>，在数据中客户端的名称与官网下载是不同的，如果不需要执行任务列表中的<strong>启动游戏</strong>，可无视此差异。</li><li>关于下载渠道<strong>谷歌版本</strong>，在数据中客户端的名称与官网下载是不同的，如果不需要执行任务列表中的<strong>启动biubiu</strong>，可无视此差异。</li></ul><h2 id="开启一键解放双手" tabindex="-1">开启一键解放双手 <a class="header-anchor" href="#开启一键解放双手" aria-label="Permalink to “开启一键解放双手”">​</a></h2><ul><li>勾选想要执行的任务，点击“开始任务”运行你的 <code>MaaYuan</code> 吧。</li><li>更多关于任务的说明请继续阅读<a href="./../Manual/Overview.html">项目概览</a> 或 <a href="./../Features/HomeInterface.html">功能介绍</a>。</li></ul><h2 id="常见首次启动异常" tabindex="-1">常见首次启动异常 <a class="header-anchor" href="#常见首次启动异常" aria-label="Permalink to “常见首次启动异常”">​</a></h2><ul><li>长时间卡在依赖安装：请查阅<a href="./../FAQ/01-general-issues.html">【常见问题】</a>。</li><li>双击无反应：检查运行库是否安装及系统权限。</li><li>模拟器未适配：优先确认分辨率、ADB 连接与后台保活设置。</li></ul>',16))])}const P=n(c,[["render",g]]);export{k as __pageData,P as default};
